INSERT INTO `microretos` (`id`, `titulo`, `empresa_id`, `ciclo_id`, `empresa_nombre`, `quien_es`, `dia_a_dia`, `pregunta_reto`, `dificultades`, `que_necesitan`, `limitaciones`, `prototipos`, `ods_sugeridos`, `soft_skills`, `evaluacion_oficial`, `tips_profesorado`, `nivel_grupo`, `ciclo`, `modulo`, `duracion`, `created_at`, `updated_at`, `es_simulado`) VALUES (1,'Optimización de la gestión de stock mediante digitalización',298,15,'Trapitos y nudos','Trapitos y nudos es una empresa dedicada a la venta de zapatos barefoot, que se caracteriza por su enfoque en la comodidad y naturalidad del calzado.','Actualmente, la empresa gestiona su inventario de manera manual, lo que resulta en pérdida frecuente de datos, errores y falta de comunicación eficiente.','¿Cómo podemos implementar un sistema digital para gestionar el stock de manera eficiente y reducir errores?','[\"Errores frecuentes en el inventario\", \"Falta de comunicación entre departamentos\"]','[\"Un sistema de gestión de inventario digital\", \"Mejorar la comunicación interna\"]','[\"Presupuesto limitado para nuevas tecnologías\", \"Requiere formación del personal en nuevas herramientas\"]','[\"Prototipo de sistema de gestión de inventario\", \"Plan de comunicación digital interno\"]','[\"ODS 8: Trabajo decente y crecimiento económico\", \"ODS 9: Industria, innovación e infraestructura\"]','[\"Adaptabilidad\", \"Resolución de problemas\"]','[{\"ce\": [\"Describir los componentes de un sistema informático\", \"Implementar software que optimice procesos empresariales\"], \"ra\": \"Configurar y gestionar sistemas informáticos en red, asegurando su funcionamiento.\", \"modulo\": \"Sistemas informáticos\"}, {\"ce\": [\"Diseñar una base de datos para un sistema de gestión de inventario\"], \"ra\": \"Diseñar y gestionar bases de datos asegurando su integridad y disponibilidad.\", \"modulo\": \"Bases de datos\"}]','[\"Gestión de Aula: Organizar a los alumnos en grupos de trabajo, asignando roles como analista de sistemas, desarrollador y gestor de proyectos. Fomentar la colaboración entre roles para simular un entorno de trabajo real, donde la comunicación y la gestión del tiempo son esenciales.\", \"Prevención de Bloqueos: Un problema común puede ser la falta de experiencia en el uso de nuevas tecnologías. Para abordar esto, el profesor debe proporcionar recursos de aprendizaje autodirigido y guías paso a paso. Facilitar sesiones de preguntas y respuestas para clarificar dudas y asegurar que todos los alumnos se sientan cómodos con las herramientas antes de iniciar el desarrollo del prototipo.\"]','Medio','Desarrollo de Aplicaciones Web','Transversal','1 a 2 semanas','2026-02-27 11:14:36','2026-02-27 11:14:36',0),(2,'Optimización de Gestión de Proveedores',31,144,'TALLERES DANIEL SL','TALLERES DANIEL SL es una micropyme de 1-10 empleados que opera en el sector de los talleres, especializada en arreglo de chapa y pintura.','La empresa recibe vehículos para realizar arreglos de chapa y pintura, pero enfrenta problemas en la gestión de proveedores y la digitalización del stock.','¿Cómo podríamos implementar una solución económica para optimizar la gestión de proveedores y digitalizar el stock?','[\"Dificultad para encontrar proveedores\", \"Problemas en la digitalización del stock\"]','[\"Sistema económico para gestión de proveedores\", \"Digitalización efectiva del stock\"]','[\"No debe ser caro\", \"Implementación rápida en 1 a 2 semanas\"]','[\"Sistema de gestión de stock digital\", \"Plataforma de comunicación con proveedores\"]','[\"ODS 9: Industria, Innovación e Infraestructura\", \"ODS 12: Producción y Consumo Responsables\"]',NULL,'[{\"ce\": [\"Identificar herramientas digitales\", \"Aplicar tecnologías digitales\"], \"ra\": \"Implementar tecnologías digitales en procesos productivos.\", \"modulo\": \"Digitalización aplicada a los sectores productivos (GM)\", \"aplicacion\": \"Digitalizar el proceso de gestión de stock y proveedores mediante herramientas asequibles.\"}, {\"ce\": [\"Gestionar relaciones con proveedores\"], \"ra\": \"Desarrollar habilidades de comunicación y gestión.\", \"modulo\": \"Itinerario personal para la empleabilidad I\", \"aplicacion\": \"Mejorar la comunicación y gestión de relaciones con proveedores.\"}]','[\"Gestión de Aula: Asignar roles de gestor de proveedores y encargado de digitalización a diferentes estudiantes.\", \"Prevención de Bloqueos: Es probable que el alumnado se atasque en la identificación de soluciones digitales asequibles; guiarles hacia el uso de software de código abierto.\"]','Medio','Electromecánica de Vehículos Automóviles','Transversal','1 a 2 semanas','2026-03-02 13:41:01','2026-03-02 13:41:01',0),(4,'Optimización Digital de Albaranes en Agrilor',59,83,'Agrilor','Agrilor es una empresa del sector industrial especializada en la comercialización de maquinaria agrícola en África.','Actualmente, el proceso de albaranes presenta errores por stock debido a registros manuales ineficientes.','¿Cómo podríamos digitalizar y automatizar el registro de albaranes para reducir errores de stock?','[\"Errores frecuentes en el stock\", \"Insatisfacción del cliente\"]','[\"Automatización del proceso de registro\", \"Solución económica y eficiente\"]','[\"Equipos obsoletos\", \"Resistencia al cambio\"]','[\"Flujo de trabajo digital\", \"Propuesta de herramienta de lectura de albaranes\"]','[\"ODS 9: Industria, Innovación e Infraestructura\", \"ODS 12: Producción y Consumo Responsables\"]',NULL,'[{\"ce\": [\"Familiarización con herramientas digitales\", \"Optimización de procesos de venta\"], \"ra\": \"Aplicación de técnicas digitales en procesos de venta.\", \"modulo\": \"Técnicas de venta en jardinería y floristería\", \"aplicacion\": \"Mejora en el manejo eficiente del stock y fidelización del cliente.\"}, {\"ce\": [\"Implementación de métodos sostenibles\"], \"ra\": \"Integración de procesos sostenibles y tecnológicos.\", \"modulo\": \"Sostenibilidad aplicada al sistema productivo\", \"aplicacion\": \"Uso eficiente de los recursos tecnológicos para minimizar errores y desperdicios.\"}]','[\"Gestión de Aula: Organiza al alumnado en equipos para fomentar la colaboración y asigna roles específicos como gestor de proyecto, técnico y comunicador.\", \"Prevención de Bloqueos: Posibilidad de atasco al trabajar con herramientas digitales; guía a los estudiantes en la búsqueda de soluciones en línea y proporciona tutoriales básicos.\"]','Medio','Jardinería y Floristería','Transversal','1 a 2 semanas','2026-03-09 12:44:55','2026-03-09 12:44:55',0),(5,'Optimización del Registro de Albaranes en Agrilor',59,129,'Agrilor','Agrilor es una micropyme del sector industrial especializada en la comercialización y exportación de maquinaria agrícola.','Actualmente, el proceso de registro de albaranes presenta errores frecuentes debido a sistemas obsoletos.','¿Cómo podríamos mejorar la precisión y eficiencia del registro de albaranes en Agrilor?','[\"Errores en el stock\", \"Falta de comunicación interna\"]','[\"Una herramienta efectiva para el registro de albaranes\", \"Reducción de errores de stock\"]','[\"Equipos obsoletos\", \"Presupuesto limitado\"]','[\"Prototipo de aplicación para registro de albaranes\", \"Plan de integraciones para equipos existentes\"]','[\"ODS 9: Industria, Innovación e Infraestructura\", \"ODS 12: Producción y Consumo Responsables\"]',NULL,'[{\"ce\": [\"Identificar áreas de mejora en el proceso productivo\", \"Implementar cambios tecnológicos sostenibles\"], \"ra\": \"Desarrollar estrategias para mejorar procesos productivos sostenibles.\", \"modulo\": \"Sostenibilidad aplicada al sistema productivo\", \"aplicacion\": \"Utilizar conceptos de optimización para desarrollar un sistema más eficiente y menos propenso a errores.\"}, {\"ce\": [\"Diseñar soluciones innovadoras para problemas cotidianos\"], \"ra\": \"Desarrollar habilidades para resolver problemas empresariales.\", \"modulo\": \"Itinerario personal para la empleabilidad II\", \"aplicacion\": \"Apl